fn fibonacci(n: usize) -> Vec<i32> {
    // We assume n >= 2 as per the problem statement.
    let mut fibs = Vec::with_capacity(n);
    
    // Initialize first two Fibonacci numbers.
    fibs.push(0);
    fibs.push(1);
    
    // Compute subsequent Fibonacci numbers iteratively.
    for i in 2..n {
        // Safe to unwrap because i-1 and i-2 always valid here.
        let next = fibs[i - 1] + fibs[i - 2];
        fibs.push(next);
    }
    
    fibs
}